<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\{Branch,Category,Customer,Department,PriceList,PriceListItem,Product,Supplier,Unit,Warehouse}; use App\Support\ApiResponse; use Illuminate\Http\{JsonResponse,Request}; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Validator;
class DataExchangeController extends Controller {
 private const RESOURCES=['products','suppliers','customers','branches','departments','warehouses','price-list-items'];
 public function authorizeExport(Request $r):JsonResponse{$d=$r->validate(['page'=>'required|string|max:100','format'=>'required|in:xlsx,pdf,doc']);return ApiResponse::success(['authorized'=>true]+$d);}
 public function import(Request $r,string $resource):JsonResponse{abort_unless(in_array($resource,self::RESOURCES,true),404,'Import is not supported for this list.');$rules=['rows'=>'required|array|min:1|max:5000','rows.*'=>'required|array'];if($resource==='price-list-items')$rules['price_list_id']=['required','integer'];$data=$r->validate($rules);$org=(int)$r->user()->organization_id;$priceList=$resource==='price-list-items'?PriceList::where('organization_id',$org)->findOrFail($data['price_list_id']):null;$prepared=[];$errors=[];foreach($data['rows'] as $index=>$raw){$row=collect($raw)->mapWithKeys(fn($value,$key)=>[str((string)$key)->lower()->replaceMatches('/[^a-z0-9]+/','_')->trim('_')->toString()=>$value])->all();[$rules,$values]=$this->prepare($resource,$row,$index+1);$validator=Validator::make($values,$rules);if($validator->fails())$errors[]=['row'=>$index+2,'errors'=>$validator->errors()->all()];else$prepared[]=$values;}if($errors)return ApiResponse::error('Import validation failed. No rows were saved.',422,['rows'=>$errors]);DB::transaction(function()use($prepared,$resource,$org,$priceList){foreach($prepared as $row)$this->save($resource,$row,$org,$priceList);});return ApiResponse::success(['resource'=>$resource,'imported'=>count($prepared)],200,['message'=>count($prepared).' rows imported.']);}
 private function prepare(string $resource,array $r,int $rowNumber=1):array{return match($resource){'products'=>[['sku'=>'required|string|max:100','name'=>'required|string|max:255','cost_price'=>'required|numeric|min:0','selling_price'=>'required|numeric|min:0','tax_rate'=>'nullable|numeric|min:0','reorder_level'=>'nullable|numeric|min:0','category'=>'nullable|string','unit'=>'nullable|string'],['sku'=>$this->firstFilled($r['sku']??null,$r['item_code']??null),'name'=>$this->firstFilled($r['name']??null,$r['product']??null,$r['description']??null),'cost_price'=>$this->amount($this->firstFilled($r['cost_price']??null,$r['cost']??null)),'selling_price'=>$this->amount($this->firstFilled($r['selling_price']??null,$r['price']??null,$r['cost_price']??null,$r['cost']??null)),'tax_rate'=>$this->amount($this->firstFilled($r['tax_rate']??null,$r['vat']??null,0)),'reorder_level'=>$this->amount($this->firstFilled($r['reorder_level']??null,0)),'category'=>$r['category']??null,'unit'=>$r['unit']??null]],'suppliers'=>[['name'=>'required|string|max:255','email'=>'nullable|email','phone'=>'nullable|string|max:50'],['name'=>$r['name']??null,'email'=>$r['email']??null,'phone'=>$r['phone']??null]],'customers'=>[['name'=>'required|string|max:255','email'=>'nullable|email','phone'=>'nullable|string|max:50','customer_type'=>'required|in:retail,wholesale'],['name'=>$r['name']??null,'email'=>$r['email']??null,'phone'=>$r['phone']??null,'customer_type'=>strtolower($r['customer_type']??$r['type']??'retail')]],'branches'=>[['name'=>'required|string|max:255','code'=>'required|string|max:50'],['name'=>$r['name']??null,'code'=>$r['code']??null,'email'=>$r['email']??null,'phone'=>$r['phone']??null,'address'=>$r['address']??null]],'departments'=>[['name'=>'required|string|max:255','code'=>'required|string|max:50','branch_code'=>'required|string'],['name'=>$r['name']??null,'code'=>$r['code']??null,'branch_code'=>$r['branch_code']??$r['branch']??null]],'price-list-items'=>[['item_code'=>'nullable|string|max:100','description'=>'required|string|max:255','item_type'=>'nullable|string|max:100','brand'=>'nullable|string|max:100','model'=>'nullable|string|max:100','unit'=>'required|string|max:50','unit_price'=>'required|numeric|min:0','vat_rate'=>'nullable|numeric|between:0,100'],['item_code'=>$r['item_code']??sprintf('IMPORTED-%04d',$rowNumber),'description'=>trim((string)($r['product']??$r['description']??'')),'item_type'=>trim((string)($r['item_type']??'Auto Spare'))?:'Auto Spare','brand'=>$r['brand']??null,'model'=>$r['model']??null,'unit'=>trim((string)($r['unit']??'Each')),'unit_price'=>$this->amount($r['unit_price_vat_excl']??$r['unit_price']??$r['price']??null),'vat_rate'=>$this->amount($r['vat_rate']??$r['vat']??0)??0]],default=>[['name'=>'required|string|max:255','code'=>'required|string|max:50','branch_code'=>'required|string'],['name'=>$r['name']??null,'code'=>$r['code']??null,'branch_code'=>$r['branch_code']??$r['branch']??null,'address'=>$r['address']??null]]};}
 private function firstFilled(mixed ...$values):mixed{foreach($values as $value)if($value!==null&&trim((string)$value)!=='')return $value;return null;}
 private function amount(mixed $value):mixed{if($value===null||$value==='')return null;$clean=str_replace([',',' ','%'],'',(string)$value);return is_numeric($clean)?(float)$clean:$value;}
 private function save(string $resource,array $r,int $org,?PriceList $priceList=null):void{if($resource==='products'){$categoryId=$r['category']?Category::firstOrCreate(['organization_id'=>$org,'name'=>$r['category']])->id:null;$unitId=$r['unit']?Unit::firstOrCreate(['organization_id'=>$org,'name'=>$r['unit']],['abbreviation'=>$r['unit']])->id:null;Product::updateOrCreate(['organization_id'=>$org,'sku'=>$r['sku']],['name'=>$r['name'],'cost_price'=>$r['cost_price'],'selling_price'=>$r['selling_price'],'tax_rate'=>$r['tax_rate']??0,'reorder_level'=>$r['reorder_level']??0,'category_id'=>$categoryId,'unit_id'=>$unitId]);return;}if($resource==='suppliers'){Supplier::updateOrCreate(['organization_id'=>$org,'name'=>$r['name']],$r);return;}if($resource==='customers'){Customer::updateOrCreate(['organization_id'=>$org,'name'=>$r['name']],$r);return;}if($resource==='branches'){Branch::updateOrCreate(['organization_id'=>$org,'code'=>$r['code']],$r+['is_active'=>true]);return;}if($resource==='price-list-items'){PriceListItem::updateOrCreate(['price_list_id'=>$priceList->id,'item_code'=>$r['item_code']],['product_id'=>null,'description'=>$r['description'],'item_type'=>$r['item_type'],'brand'=>$r['brand'],'model'=>$r['model'],'unit'=>$r['unit'],'unit_price'=>$r['unit_price'],'vat_rate'=>$r['vat_rate']??0,'notes'=>null]);return;}$branch=Branch::where('organization_id',$org)->where('code',$r['branch_code'])->first();abort_unless($branch,422,"Branch code {$r['branch_code']} was not found.");if($resource==='departments'){Department::updateOrCreate(['organization_id'=>$org,'code'=>$r['code']],['name'=>$r['name'],'branch_id'=>$branch->id,'is_active'=>true]);return;}Warehouse::updateOrCreate(['organization_id'=>$org,'code'=>$r['code']],['name'=>$r['name'],'branch_id'=>$branch->id,'address'=>$r['address']??null,'is_active'=>true]);}
}
